/* Clearline scroll story — GSAP ScrollTrigger pin + scrub, Lenis smooth scroll.
   Falls back to a static gallery when GSAP is unavailable or motion is reduced. */
(function () {
  'use strict';

  var root = document.documentElement;

  /* Header shadow on scroll */
  var header = document.querySelector('.site-header');
  function onScrollHeader() {
    if (header) header.classList.toggle('scrolled', window.scrollY > 8);
  }
  window.addEventListener('scroll', onScrollHeader, { passive: true });
  onScrollHeader();

  var reduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  var hasGsap = typeof window.gsap !== 'undefined' && typeof window.ScrollTrigger !== 'undefined';

  if (!hasGsap || reduced) {
    root.classList.add('static');
    initSpaces();
    initForm();
    return;
  }

  window.gsap.registerPlugin(window.ScrollTrigger);

  /* Lenis smooth scroll, wired into ScrollTrigger */
  var lenis = null;
  if (typeof window.Lenis !== 'undefined') {
    lenis = new window.Lenis({ lerp: 0.1 });
    lenis.on('scroll', window.ScrollTrigger.update);
    window.gsap.ticker.add(function (time) { lenis.raf(time * 1000); });
    window.gsap.ticker.lagSmoothing(0);
  }

  /* Anchor links through Lenis when present */
  document.querySelectorAll('a[href^="#"]').forEach(function (a) {
    a.addEventListener('click', function (e) {
      var id = a.getAttribute('href');
      if (id.length < 2) return;
      var target = document.querySelector(id);
      if (!target) return;
      e.preventDefault();
      if (lenis) lenis.scrollTo(target, { offset: -72 });
      else target.scrollIntoView({ behavior: 'smooth' });
    });
  });

  /* ---- The five stages ---- */
  var stages = [
    { num: 'Stage 1 of 5', title: 'Monday, 8 AM', text: 'The weekend did its worst. Papers everywhere, bins full, coffee rings on every desk.' },
    { num: 'Stage 2 of 5', title: 'The crew arrives', text: 'Uniformed, vetted, and on time. One crew lead walks the floor while the team sets up.' },
    { num: 'Stage 3 of 5', title: 'Deep clean', text: 'Floors mopped, restrooms sanitized, kitchens degreased. The heavy work, done right.' },
    { num: 'Stage 4 of 5', title: 'Detail pass', text: 'Desks wiped, glass polished, handles disinfected. The part most crews skip.' },
    { num: 'Stage 5 of 5', title: 'Spotless', text: 'Monday, 9 AM. Your team walks into a space that smells clean and looks new.' }
  ];

  var figures = Array.prototype.slice.call(document.querySelectorAll('.stage'));
  var stageNum = document.getElementById('stageNum');
  var stageTitle = document.getElementById('stageTitle');
  var stageText = document.getElementById('stageText');
  var meterNum = document.getElementById('meterNum');
  var meterFill = document.getElementById('meterFill');
  var storyFill = document.getElementById('storyFill');
  var currentStage = -1;

  function setStage(i) {
    if (i === currentStage) return;
    currentStage = i;
    var s = stages[i];
    stageNum.textContent = s.num;
    stageTitle.textContent = s.title;
    stageText.textContent = s.text;
    figures.forEach(function (f, j) { f.classList.toggle('is-active', j === i); });
  }

  function setMeter(p) {
    var pct = Math.round(p * 100);
    meterNum.textContent = pct;
    meterFill.style.width = pct + '%';
    storyFill.style.width = (p * 100) + '%';
  }

  /* One pinned section. Opacity per stage is computed from scroll progress,
     so the crossfades and the label can never drift apart. */
  window.ScrollTrigger.create({
    trigger: '#story',
    start: 'top top',
    end: '+=320%',
    scrub: 1,
    pin: true,
    anticipatePin: 1,
    onUpdate: function (self) {
      var p = self.progress;
      setMeter(p);
      renderStages(p);
    }
  });

  /* Stage i is fully visible across [i/5, (i+1)/5], crossfading 0.1 of
     progress either side of each boundary. First stage starts visible,
     last stage stays visible. */
  function stageOpacity(i, p) {
    var w = 0.1, start = i / 5, end = (i + 1) / 5, op = 1;
    if (i > 0) op = Math.min(op, clamp((p - (start - w / 2)) / w, 0, 1));
    if (i < 4) op = Math.min(op, clamp(((end + w / 2) - p) / w, 0, 1));
    return op;
  }
  function clamp(v, lo, hi) { return Math.max(lo, Math.min(hi, v)); }

  function renderStages(p) {
    figures.forEach(function (fig, i) {
      var op = stageOpacity(i, p);
      fig.style.opacity = op;
      fig.style.transform = 'scale(' + (1.08 - 0.08 * op).toFixed(3) + ')';
    });
    setStage(Math.min(4, Math.floor(p * 5)));
  }

  renderStages(0);
  setMeter(0);

  initSpaces();
  initForm();

  /* ---- Space selector ---- */
  function initSpaces() {
    var data = {
      office: {
        img: 'data:image/jpeg;base64,', alt: 'A spotless modern office', title: 'Offices',
        specs: ['Desks, floors, restrooms, kitchens', 'After-hours crews, zero disruption to your workday', 'Daily, weekly, or bi-weekly cadence'],
        cta: 'Get a quote for your office'
      },
      clinic: {
        img: 'data:image/jpeg;base64,', alt: 'A bright, spotless clinic reception and waiting area', title: 'Clinics',
        specs: ['Exam rooms, waiting areas, high-touch disinfection', 'HIPAA-aware crews and checklists', 'Daily service with same-day turnaround'],
        cta: 'Get a quote for your clinic'
      },
      retail: {
        img: 'data:image/jpeg;base64,', alt: 'A bright, spotless retail store interior', title: 'Retail',
        specs: ['Sales floor, fitting rooms, restrooms', 'Before-open or after-close shifts', 'Weekly deep cleans plus daily touch-ups'],
        cta: 'Get a quote for your store'
      }
    };

    var cards = Array.prototype.slice.call(document.querySelectorAll('.space-card'));
    var detail = document.getElementById('spaceDetail');
    var img = document.getElementById('spaceImg');
    var title = document.getElementById('spaceTitle');
    var specs = document.getElementById('spaceSpecs');
    var cta = detail.querySelector('.btn');
    if (!detail || !cards.length) return;

    cards.forEach(function (card) {
      card.addEventListener('click', function () {
        var key = card.getAttribute('data-space');
        var d = data[key];
        if (!d) return;
        cards.forEach(function (c) {
          var on = c === card;
          c.classList.toggle('is-active', on);
          c.setAttribute('aria-selected', on ? 'true' : 'false');
        });
        img.src = d.img;
        img.alt = d.alt;
        title.textContent = d.title;
        specs.innerHTML = d.specs.map(function (s) { return '<li>' + s + '</li>'; }).join('');
        cta.textContent = d.cta;
        detail.classList.remove('swap');
        void detail.offsetWidth;
        detail.classList.add('swap');
      });
    });
  }

  /* ---- Walkthrough form (demo: no data leaves the page) ---- */
  function initForm() {
    var form = document.getElementById('walkForm');
    var note = document.getElementById('formNote');
    if (!form) return;
    form.addEventListener('submit', function (e) {
      e.preventDefault();
      var name = (form.querySelector('[name="name"]') || {}).value || 'there';
      var first = String(name).trim().split(/\s+/)[0] || 'there';
      note.textContent = 'Thanks, ' + first + '. We will call within one business day to set up your free walkthrough.';
      form.querySelector('button[type="submit"]').textContent = 'Request received ✓';
    });
  }
})();
